 s=s.replace("$$('.close-dialog').forEach(b=>b.onclick=()=>this.closeDialogs(true));","$$('.close-dialog').forEach(b=>b.onclick=()=>this.requestCloseCurrent());")
 s=s.replace("exp.textContent=hasChildren?(this.collapsed.has(n.id)?'▸':'▾'):'·';exp.disabled=!hasChildren;","exp.textContent=hasChildren?'▸':'·';exp.classList.toggle('expanded',hasChildren&&!this.collapsed.has(n.id));exp.disabled=!hasChildren;")
 s=s.replace("if(hasChildren){const box=document.createElement('div');box.className='children'+(this.collapsed.has(n.id)?' collapsed':'');children.forEach(ch=>box.appendChild(this.renderNode(ch,depth+1,keep,null)));wrap.appendChild(box)}","if(hasChildren){const box=document.createElement('div');box.className='children'+(this.collapsed.has(n.id)?' collapsed':'');const inner=document.createElement('div');inner.className='children-inner';children.forEach(ch=>inner.appendChild(this.renderNode(ch,depth+1,keep,null)));box.appendChild(inner);wrap.appendChild(box)}")
