css='''
/* v2.1.2 polish */
html,body,.app-shell{width:100%;max-width:100%;height:100%;height:100dvh;overflow:hidden}body{overscroll-behavior:none}.topbar{transform:none!important;margin-top:0!important;transition:none!important}.brand{padding-bottom:10px}.brand-divider{height:1px;margin:0 -2px 9px;background:linear-gradient(90deg,transparent,var(--violet) 12%,rgba(167,139,250,.78) 50%,var(--violet) 88%,transparent);box-shadow:0 0 8px rgba(167,139,250,.24)}.nav-details{display:block!important;max-height:420px;opacity:1;transition:max-height 220ms cubic-bezier(.22,.61,.36,1),opacity 150ms ease!important;overflow:hidden}.topbar.nav-collapsed .nav-details{max-height:0!important;opacity:0}.nav-collapse-btn{display:block;width:100%;height:13px;margin:5px 0 -3px;border:0;background:transparent;position:relative;padding:0}.nav-collapse-btn::before{content:'';position:absolute;left:50%;top:5px;width:46px;height:3px;border-radius:9px;background:#31515a;transform:translateX(-50%)}.nav-collapse-btn span::after{content:'⌃';position:absolute;left:50%;top:-5px;transform:translateX(-50%);font-size:10px;color:var(--muted);transition:transform 180ms ease}.topbar.nav-collapsed .nav-collapse-btn span::after{transform:translateX(-50%) rotate(180deg)}.expand-btn{margin-right:-20px!important;transition:transform 145ms cubic-bezier(.22,.61,.36,1)!important;transform:rotate(0deg)}.expand-btn.expanded{transform:rotate(90deg)}.children{display:grid!important;grid-template-rows:1fr;opacity:1;margin-top:6px;transition:grid-template-rows 210ms cubic-bezier(.22,.61,.36,1),opacity 145ms ease,margin-top 210ms ease;overflow:hidden}.children-inner{min-height:0;overflow:hidden;display:flex;flex-direction:column;gap:6px}.children.collapsed{display:grid!important;grid-template-rows:0fr;opacity:0;margin-top:0}.filter.secondary:focus{outline:none}.boot-intro{width:100vw;height:100dvh;transform:none!important}.boot-intro.boot-out{opacity:0!important;transform:none!important;transition:opacity 360ms ease!important}.app-reveal{animation:none!important}.title-row h1{font-size:clamp(18px,4.8vw,24px)}.overall-card,.toolbar-row>*,.filters,.node-row,.node-main{min-width:0}.node-main{overflow:hidden}.node-title,.node-desc{overflow-wrap:anywhere}@media(hover:none){.toolbar-btn:hover,.filter:hover{border-color:var(--line);color:var(--muted)}.filter.active:hover{background:rgba(97,231,242,.12);border-color:var(--cyan2);color:var(--cyan)}}@media(max-width:720px){.topbar{padding-top:max(10px,env(safe-area-inset-top));padding-left:max(7px,env(safe-area-inset-left));padding-right:max(7px,env(safe-area-inset-right))}.filters{grid-template-columns:repeat(5,minmax(0,1fr));width:100%}.filter,.filter.secondary{font-size:clamp(9px,2.6vw,11px);padding-inline:2px}}@media(max-width:380px){.filters{gap:3px}.filter,.filter.secondary{font-size:9px}.tree-scroll{padding-left:6px;padding-right:6px}}
'''
